/* 本地设计原型：归档内容与任务进度均为示例，不调用压缩引擎。 */
const $ = (s, root = document) => root.querySelector(s);
const esc = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',
  archive:'M4 5h16v16H4z M3 2h18v4H3z M10 10h4 M12 6v4',
  tasks:'M9 5h12M9 12h12M9 19h12M3 5l1 1 2-3M3 12l1 1 2-3M3 19l1 1 2-3',
  settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  open:'M3 7h7l2 2h9l-3 11H3V5h7l2 2 M3 11h17',
  plus:'M12 5v14M5 12h14', search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
  arrow:'m9 5 7 7-7 7', close:'m6 6 12 12M18 6 6 18',
  extract:'M4 15v6h16v-6M12 3v12m-5-5 5 5 5-5',
  shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z m-5 9 3 3 5-6',
  info:'M12 11v6M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  check:'m5 12 4 4L19 6', clock:'M12 6v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  pause:'M8 5v14M16 5v14', play:'m8 4 12 8-12 8z', refresh:'M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 14-2l1 2M4 17l1 2a8 8 0 0 0 14-2',
  lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4', panel:'M3 4h18v16H3zM15 4v16',
  upload:'M4 15v6h16v-6M12 16V3m-5 5 5-5 5 5', eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0'
};
function icon(name, cls='') { return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.archive}"/></svg>`; }
function fileIcon(type='7z') {
  if(type==='folder') return `<svg class="file-icon folder" viewBox="0 0 32 36" fill="none" aria-hidden="true"><path d="M2 9h11l3 4h14v18H2z" fill="currentColor" opacity=".19"/><path d="M2 9h11l3 4h14v18H2zM2 16h28" stroke="currentColor" stroke-width="1.3"/></svg>`;
  const kind = ['zip','pdf','image','code'].includes(type) ? type : '';
  const text = {image:'IMG',code:'TXT',pdf:'PDF',zip:'ZIP','7z':'7Z'}[type] || type.toUpperCase();
  return `<svg class="file-icon ${kind}" viewBox="0 0 32 36" fill="none" aria-hidden="true"><path d="M6 2h14l7 7v25H6z" fill="currentColor" opacity=".10"/><path d="M6 2h14l7 7v25H6zM20 2v8h7" stroke="currentColor" stroke-width="1.3"/><text x="16.5" y="25" text-anchor="middle">${esc(text)}</text></svg>`;
}
const sample = [
  {id:'design',name:'设计稿',type:'folder',size:'680 MB',packed:'214 MB',bytes:680,date:'2026/11/02 16:30'},
  {id:'images',name:'产品图片',type:'folder',size:'412 MB',packed:'286 MB',bytes:412,date:'2026/11/02 15:20'},
  {id:'assets',name:'品牌素材',type:'folder',size:'126 MB',packed:'89 MB',bytes:126,date:'2026/11/01 11:46'},
  {id:'pdf',name:'产品设计说明.pdf',type:'pdf',size:'8.6 MB',packed:'6.8 MB',bytes:8.6,date:'2026/11/02 18:05'},
  {id:'cover',name:'项目封面.png',type:'image',size:'4.2 MB',packed:'3.8 MB',bytes:4.2,date:'2026/11/02 17:42'},
  {id:'readme',name:'README.txt',type:'code',size:'2.4 KB',packed:'1.1 KB',bytes:.0024,date:'2026/11/01 09:12'}
];
const children = {
  design:[{id:'fig',name:'产品界面.fig',type:'code',size:'516 MB',packed:'162 MB',bytes:516,date:'2026/11/02 16:30'},{id:'preview',name:'界面预览.png',type:'image',size:'164 MB',packed:'52 MB',bytes:164,date:'2026/11/02 16:28'}],
  images:[{id:'hero',name:'主视觉.png',type:'image',size:'240 MB',packed:'168 MB',bytes:240,date:'2026/11/02 15:20'},{id:'product',name:'产品实拍.jpg',type:'image',size:'172 MB',packed:'118 MB',bytes:172,date:'2026/11/01 11:10'}],
  assets:[{id:'brand',name:'品牌规范.pdf',type:'pdf',size:'126 MB',packed:'89 MB',bytes:126,date:'2026/11/01 11:46'}]
};
const recent = [{name:'项目素材.7z',type:'7z',size:'600.4 MB',where:'D:\\工作\\项目素材',time:'今天 10:42'}, {name:'产品发布.7z',type:'7z',size:'128.6 MB',where:'D:\\工作\\产品发布',time:'今天 09:18'}, {name:'照片备份.7z',type:'7z',size:'2.4 GB',where:'D:\\备份\\照片',time:'昨天 18:35'}, {name:'设计规范.7z',type:'7z',size:'32.8 MB',where:'D:\\工作\\设计规范',time:'昨天 15:06'}];
const state = {page:'home',archiveName:'项目素材.7z',folder:'',query:'',sort:'name',asc:true,selected:new Set(),details:true,history:[...recent],tasks:[],theme:'system',brand:'../图标/logo.png',sourceNames:[],createDraft:{},extractDraft:{},nextId:1,loadError:false};
let trigger = null, toastTimer, customUrl;
try { state.theme = localStorage.getItem('new7z-theme') || 'system'; } catch {}
const media = matchMedia('(prefers-color-scheme: dark)');
function setTheme(choice) { state.theme=choice; document.documentElement.dataset.theme=choice==='system'?(media.matches?'dark':'light'):choice; try { localStorage.setItem('new7z-theme',choice); } catch {} }
setTheme(state.theme); media.addEventListener('change',()=>{if(state.theme==='system')setTheme('system');});
const nav = [['home','home','主页'],['archive','archive','压缩包'],['tasks','tasks','任务中心']];
function notify(message) { clearTimeout(toastTimer); const n=$('#notification'); n.textContent=message; n.classList.add('visible'); toastTimer=setTimeout(()=>n.classList.remove('visible'),4200); }
function navigation() {
  $('#nav-main').innerHTML=nav.map(([page,glyph,label])=>`<button onclick="handleClick(event)" class="nav-button ${state.page===page?'active':''}" data-page="${page}" title="${label}" ${state.page===page?'aria-current="page"':''}>${icon(glyph)}<span class="nav-label">${label}</span>${page==='tasks'&&state.tasks.some(t=>t.status==='running')?'<span class="count">'+state.tasks.filter(t=>t.status==='running').length+'</span>':''}</button>`).join('');
  const settings=$('[data-page="settings"]'); settings.classList.toggle('active',state.page==='settings'); if(state.page==='settings') settings.setAttribute('aria-current','page'); else settings.removeAttribute('aria-current');
  $('#settings-icon').innerHTML=icon('settings'); $('#local-note').innerHTML=icon('shield')+'<span>文件留在你的设备上</span>';
  document.querySelectorAll('.brand-image').forEach(el=>el.src=state.brand);
}
function render(focus=true) {
  navigation();
  const pages={home:homePage,archive:archivePage,tasks:tasksPage,settings:settingsPage};
  $('#main').innerHTML=pages[state.page]();
  document.title=({home:'主页',archive:state.archiveName,tasks:'任务中心',settings:'外观与图标'}[state.page])+' · New7z';
  if(focus) { const h=$('h1'); if(h){h.tabIndex=-1;h.focus({preventScroll:true});} }
}
function homePage(){return `<section class="page"><header class="page-header"><div><h1>主页</h1><p>打开压缩包，或将文件打包分享。</p></div><div class="actions"><button onclick="handleClick(event)" class="btn" data-action="open">${icon('open')}打开压缩包</button><button onclick="handleClick(event)" class="btn primary" data-action="create">${icon('plus')}新建压缩</button></div></header>
  <div class="dropzone" id="dropzone"><img class="drop-graphic brand-image" src="${esc(state.brand)}" alt="蓝色拉链文件夹"><div class="drop-content"><h2>把文件拖到这里</h2><p>压缩包直接查看，普通文件轻松打包。</p><p class="keyboard-hint">当前原型使用示例归档 · <kbd>Ctrl</kbd> + <kbd>O</kbd> 打开示例</p></div><button onclick="handleClick(event)" class="btn" data-action="pick-source">${icon('plus')}选择文件</button></div>
  <div class="quick-cards"><button onclick="handleClick(event)" class="quick-card" data-action="create">${icon('archive')}<span><strong>创建压缩包</strong><small>使用 7z，把多个文件整理成一份</small></span>${icon('arrow','chevron')}</button><button onclick="handleClick(event)" class="quick-card" data-action="open">${icon('extract')}<span><strong>查看并解压</strong><small>先看内容，再选择需要的文件</small></span>${icon('arrow','chevron')}</button></div>
  <div class="section-heading"><h2>最近使用 <span class="small muted">${state.history.length}</span></h2><button onclick="handleClick(event)" class="btn ghost" data-action="clear-history" ${!state.history.length?'disabled':''}>清空记录</button></div>
  <div class="table-frame">${state.history.length?`<table class="recent-table"><thead><tr><th>名称</th><th>格式</th><th>大小</th><th>上次打开</th><th><span class="muted">操作</span></th></tr></thead><tbody>${state.history.map((f,i)=>`<tr><td><div class="file-cell">${fileIcon(f.type)}<div><button onclick="handleClick(event)" class="file-name" data-action="recent" data-index="${i}">${esc(f.name)}</button><small>${esc(f.where)}</small></div></div></td><td><span class="pill">7z</span></td><td>${f.size}</td><td class="muted">${f.time}</td><td><button onclick="handleClick(event)" class="icon-button" data-action="recent" data-index="${i}" aria-label="打开 ${esc(f.name)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty">${icon('clock')}<h3>还没有最近记录</h3><p>打开的压缩包会显示在这里。</p><button onclick="handleClick(event)" class="btn" data-action="open">打开示例压缩包</button></div>`}</div>
  <p class="bottom-tip">${icon('shield')}<span>围绕本地文件设计，不需要账号。当前为设计原型，列表与归档内容均为示例。</span></p></section>`;}
function archiveRows(){let rows=[...(state.folder?children[state.folder]:sample)||[]].filter(f=>f.name.toLocaleLowerCase('zh-CN').includes(state.query.toLocaleLowerCase('zh-CN')));rows.sort((a,b)=>{if(state.sort==='name'&&(a.type==='folder')!==(b.type==='folder'))return a.type==='folder'?-1:1;const mb=x=>parseFloat(x)*(x.includes('KB')?.001:1);let n=state.sort==='size'?a.bytes-b.bytes:state.sort==='packed'?mb(a.packed)-mb(b.packed):a[state.sort].localeCompare(b[state.sort],'zh-CN');return state.asc?n:-n;});return rows;}
function archiveTable(){const rows=archiveRows();return `<table><thead><tr><th class="check-cell"><input type="checkbox" id="select-all" aria-label="选择当前列表全部文件" ${rows.length&&rows.every(f=>state.selected.has(f.id))?'checked':''} ${!rows.length?'disabled':''}></th>${[['name','名称'],['size','大小'],['packed','压缩后'],['date','修改时间']].map(([k,v])=>`<th ${state.sort===k?'aria-sort="'+(state.asc?'ascending':'descending')+'"':''}><button onclick="handleClick(event)" data-action="sort" data-sort="${k}">${v}${state.sort===k?(state.asc?' ↑':' ↓'):''}</button></th>`).join('')}</tr></thead><tbody>${rows.map(f=>`<tr class="${state.selected.has(f.id)?'selected':''}"><td class="check-cell"><input type="checkbox" data-select="${f.id}" aria-label="选择 ${esc(f.name)}" ${state.selected.has(f.id)?'checked':''}></td><td><div class="file-cell">${fileIcon(f.type)}<button onclick="handleClick(event)" class="file-name" data-action="file" data-id="${f.id}">${esc(f.name)}</button></div></td><td>${f.size}</td><td class="muted">${f.packed}</td><td class="muted small">${f.date}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">'+icon('search')+'<h3>没有找到匹配的文件</h3><p>试试其他名称，或清空搜索。</p><button onclick="handleClick(event)" class="btn" data-action="clear-search">清空搜索</button></div>':''}`;}
function detailPanel(){const all=state.folder?children[state.folder]:sample;const f=state.selected.size===1?all.find(x=>state.selected.has(x.id)):null;return `<aside class="detail-panel" aria-label="归档属性">${fileIcon(f?f.type:'7z')}<h3>${esc(f?f.name:state.archiveName)}</h3><span class="pill">${f?(f.type==='folder'?'文件夹':'归档内文件'):'7z 压缩包'}</span><dl><div><dt>原始大小</dt><dd>${f?f.size:'1,230.8 MB'}</dd></div><div><dt>压缩后</dt><dd>${f?f.packed:'600.4 MB'}</dd></div><div><dt>压缩方法</dt><dd>LZMA2</dd></div><div><dt>加密</dt><dd>无</dd></div><div><dt>当前目录</dt><dd>${state.folder?esc(sample.find(f=>f.id===state.folder).name):'根目录'}</dd></div></dl>${!f?`<div class="size-visual"><div class="size-label"><span>原始文件</span><span>1,230.8 MB</span></div><div class="bar"><span style="width:100%;opacity:.25"></span></div><div class="size-label"><span>压缩包</span><span>600.4 MB</span></div><div class="bar"><span style="width:48.8%"></span></div><p>${icon('check')} 体积减少约 51.2%</p><div class="small muted" style="margin-top:8px">示例数值，非实时测量</div></div>`:''}${f&&f.type!=='folder'?previewButton(f):''}</aside>`;}
function archivePage(){return `<section class="page"><header class="page-header"><div class="archive-heading">${fileIcon('7z')}<div><h1>${esc(state.archiveName)}</h1><p>D:\\工作\\${esc(state.archiveName)} <span class="pill">示例</span></p></div></div><button onclick="handleClick(event)" class="btn primary" data-action="extract">${icon('extract')}<span id="extract-label">${state.selected.size?'解压选中 '+state.selected.size+' 项':'全部解压'}</span></button></header>
  <div class="toolbar"><div class="actions"><button onclick="handleClick(event)" class="btn ghost" data-action="create">${icon('plus')}添加到新包</button><button onclick="handleClick(event)" class="btn ghost" id="preview-selected" data-action="preview-selected" ${!canPreviewSelection()?'disabled':''}>${icon('eye')}预览</button><button onclick="handleClick(event)" class="btn ghost" data-action="test">${icon('shield')}测试完整性</button></div><div class="actions"><button onclick="handleClick(event)" class="btn ghost" data-action="archive-menu" aria-haspopup="menu">更多 ⋯</button><button onclick="handleClick(event)" class="btn ghost" data-action="toggle-details" aria-pressed="${state.details}">${icon('panel')}属性</button></div></div>
  <div class="path-search"><div class="breadcrumbs" aria-label="归档路径">${icon('archive')}<button onclick="handleClick(event)" data-action="root">根目录</button>${state.folder?icon('arrow')+'<span aria-current="location">'+esc(sample.find(f=>f.id===state.folder).name)+'</span>':''}</div><div class="search">${icon('search')}<input id="file-search" type="search" aria-label="搜索当前目录" placeholder="搜索当前目录" value="${esc(state.query)}"><button onclick="handleClick(event)" class="icon-button" data-action="clear-search" aria-label="清空搜索" ${!state.query?'hidden':''}>${icon('close')}</button></div></div>
  ${state.loadError?`<div class="empty">${icon('info')}<h3>无法读取压缩包</h3><p>这是读取失败状态演示。实际应用将保留路径与引擎错误。</p><button onclick="handleClick(event)" class="btn" data-action="retry-load">重新读取</button></div>`:`<div class="archive-layout ${!state.details?'no-details':''}"><div><div class="table-frame archive-table" id="archive-table">${archiveTable()}</div><div class="list-summary" id="list-summary">${archiveRows().length} 个项目${state.selected.size?' · 已选择 '+state.selected.size+' 项':''}</div></div><div id="details-slot">${state.details?detailPanel():''}</div></div>`}
  <p class="bottom-tip">${icon('info')}<span>点击图片或文本可预览，文件夹可进入。<button onclick="handleClick(event)" class="btn ghost" data-action="load-error">演示读取失败</button></span></p></section>`;}
function refreshTable(){ $('#preview-selected').disabled=!canPreviewSelection();$('#archive-table').innerHTML=archiveTable();$('#list-summary').textContent=archiveRows().length+' 个项目'+(state.selected.size?' · 已选择 '+state.selected.size+' 项':'');$('#extract-label').textContent=state.selected.size?'解压选中 '+state.selected.size+' 项':'全部解压';$('#details-slot').innerHTML=state.details?detailPanel():'';const clear=$('[data-action="clear-search"]');if(clear)clear.hidden=!state.query; }
function taskCard(t){const status={running:'正在'+t.verb,paused:'已暂停',completed:'已完成',failed:'失败',cancelled:'已取消'}[t.status];return `<article class="task-card" data-task="${t.id}"><div class="task-top"><div class="task-name">${fileIcon('7z')}<div><strong>${esc(t.name)}</strong><p>${esc(t.verb)} · ${esc(t.destination)} · 模拟任务</p></div></div><span class="pill ${t.status==='completed'?'success':t.status==='failed'?'danger-text':''}" data-task-status>${status}</span></div><div class="bar task-progress" role="progressbar" aria-label="${esc(t.name)} 模拟进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${t.progress}"><span style="width:${t.progress}%"></span></div><div class="task-meta"><span data-task-phase>${t.status==='running'?'正在处理示例文件':status}</span><span data-task-progress>${t.progress}%</span></div>${t.status==='failed'?'<p class="error-line">输出目录没有写入权限（失败示例）。请修改目标目录后重试。</p>':''}<div class="actions">${['running','paused'].includes(t.status)?`<button onclick="handleClick(event)" class="btn" data-action="pause-task" data-id="${t.id}">${icon(t.status==='paused'?'play':'pause')}${t.status==='paused'?'继续演示':'暂停演示'}</button><button onclick="handleClick(event)" class="btn ghost danger" data-action="cancel-task" data-id="${t.id}">取消任务</button>`:`${t.status==='failed'?`<button onclick="handleClick(event)" class="btn" data-action="retry-task" data-id="${t.id}">${icon('refresh')}修改目录并重试</button>`:''}${t.status==='completed'?`<button onclick="handleClick(event)" class="btn" data-action="task-result" data-id="${t.id}">查看结果说明</button>`:''}`}</div></article>`;}
function tasksPage(){return `<section class="page"><header class="page-header"><div><h1>任务中心</h1><p>查看压缩与解压进度，完成后再继续。</p></div><button onclick="handleClick(event)" class="btn" data-action="create">${icon('plus')}新建压缩</button></header><div class="task-info">${icon('info')}<span>这里演示任务状态与反馈，不执行真实压缩。模拟暂停只影响进度演示。</span></div><div class="section-heading"><h2>全部任务 <span class="small muted">${state.tasks.length}</span></h2><button onclick="handleClick(event)" class="btn ghost" data-action="failure-task">添加失败示例</button></div><div class="task-list">${state.tasks.length?state.tasks.map(taskCard).join(''):`<div class="empty">${icon('tasks')}<h3>还没有任务</h3><p>新建压缩或解压后，可在这里查看进度。</p><button onclick="handleClick(event)" class="btn primary" data-action="create">新建压缩</button></div>`}</div></section>`;}
function settingsPage(){return `<section class="page"><header class="page-header"><div><h1>外观与图标</h1><p>让 New7z 更适合你的桌面。</p></div></header><div class="settings-content"><section class="setting-block"><h2>应用主题</h2><div class="setting-card setting-row"><div><h3>选择显示模式</h3><p>跟随 Windows，或单独设置应用外观。</p></div><div class="theme-choices" role="group" aria-label="应用主题">${[['system','跟随系统'],['light','浅色'],['dark','深色']].map(([v,n])=>`<label class="theme-option"><input type="radio" name="theme" value="${v}" ${state.theme===v?'checked':''}>${n}</label>`).join('')}</div></div></section>
  <section class="setting-block"><h2>应用内图标</h2><div class="setting-card"><div class="icon-setting"><div class="icon-showcase"><img class="brand-image" src="${esc(state.brand)}" alt="当前应用图标"><div class="mini-icons">${[16,32,48].map(s=>`<figure><img src="${esc(state.brand)}" width="${s}" height="${s}" alt="${s} 像素预览"><figcaption>${s}</figcaption></figure>`).join('')}</div></div><div class="icon-copy"><h3>${customUrl?'自定义图标 · 当前会话':'蓝色拉链 · 默认图标'}</h3><p>可以替换应用内品牌图标，预览不同尺寸的显示效果。支持 PNG / ICO，最大 10 MB，尺寸不超过 4096 × 4096。</p><div class="actions"><button onclick="handleClick(event)" class="btn" data-action="pick-icon" aria-describedby="icon-error">${icon('upload')}替换应用内图标</button><button onclick="handleClick(event)" class="btn ghost" data-action="reset-icon" ${!customUrl?'disabled':''}>恢复默认</button></div><div class="inline-error" id="icon-error" role="status"></div><p class="small">自选图片只在当前会话中预览，不会上传。</p></div></div><p class="setting-footnote">当前 Logo 自带深色背景。正式版将分别提供透明 PNG、多分辨率 ICO 与构建资源。</p></div></section>
  <section class="setting-block"><h2>格式图标包 <span class="pill">设计预览</span></h2><div class="setting-card"><div class="setting-row"><div><h3>流畅渐变</h3><p>沿用工程提供的格式图标合集，按格式分配独立图标。</p></div><span class="pill">原图素材</span></div><div class="asset-strip">${[['7z','7Z'],['rar','RAR'],['tar','TAR'],['gz','GZ'],['xz','XZ']].map(([c,n])=>`<div class="asset-tile"><div class="sheet-icon sheet-${c}" role="img" aria-label="${n} 图标素材"></div>${n}</div>`).join('')}</div><p class="setting-footnote">上方仅裁切预览现有合集。正式图标包需独立透明素材与格式映射；图标不代表已支持相应格式。</p></div></section>
  <section class="setting-block"><h2>Windows 图标</h2><div class="setting-card"><h3>应用内预览与系统图标分别管理</h3><p class="setting-footnote">EXE 与任务栏图标属于构建资源；资源管理器文件图标需要独立的关联设置与系统缓存刷新。当前原型只替换应用内图片，不修改系统配置。</p></div></section></div></section>`;}

const dialog=$('#dialog');
dialog.addEventListener('keydown',e=>{
  if(e.isComposing&&e.key==='Enter'){e.preventDefault();return;}
  if(e.key!=='Tab')return;
  const focusable=Array.from(dialog.querySelectorAll('button,input,select,summary,[tabindex="0"]')).filter(el=>!el.disabled&&el.getClientRects().length);
  const first=focusable[0],last=focusable[focusable.length-1];
  if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}
  else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}
});
function showDialog(title,subtitle,body,footer,onSubmit){
  if(dialog.open) dialog.close();
  dialog.classList.remove('preview-dialog');
  trigger=document.activeElement;
  dialog.innerHTML=`<form class="dialog-inner" id="dialog-form" novalidate><div class="dialog-header"><div><h2 id="dialog-title">${title}</h2>${subtitle?'<p>'+subtitle+'</p>':''}</div><button onclick="handleClick(event)" class="icon-button" type="button" data-action="close-dialog" aria-label="关闭对话框">${icon('close')}</button></div><div class="dialog-body">${body}</div><div class="dialog-footer">${footer}</div></form>`;
  $('#dialog-form').addEventListener('submit',e=>{e.preventDefault();if(onSubmit)onSubmit(new FormData(e.currentTarget));});
  dialog.showModal();
  const first=$('[autofocus]',dialog); if(first) first.focus();
}
dialog.addEventListener('close',()=>{if(trigger&&trigger.isConnected)trigger.focus({preventScroll:true});});
dialog.addEventListener('cancel',()=>{saveDraft();});
function closeDialog(){saveDraft();dialog.close();}
function saveDraft(){if(!dialog.open)return;const form=$('#dialog-form');const kind=form?.dataset.kind;if(kind){const d=Object.fromEntries(new FormData(form));delete d.password;delete d.encryptNames;if(kind==='extract'){d.subfolder=form.elements.subfolder.checked;d.openAfter=form.elements.openAfter.checked;}state[kind+'Draft']=d;}}
function validateName(name){if(!name.trim())return '请输入压缩包名称。';if(/[<>:"/\\|?*\u0000-\u001F]/.test(name))return '名称不能包含 < > : " / \\ | ? * 等字符。';if(/[. ]$/.test(name))return '名称不能以空格或句点结尾。';if(/^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(name))return '此名称是 Windows 保留设备名，请换一个名称。';return '';}
function fieldError(id,message){const input=$('#'+id);const err=$('#'+id+'-error');input.setAttribute('aria-invalid',String(!!message));err.textContent=message;if(message)input.focus();return !!message;}
function createDialog(){const d=state.createDraft;const source=state.sourceNames.length?state.sourceNames.join('、'):'项目素材（示例）';showDialog('新建压缩包','整理成一份，分享更方便。',`<div class="source-summary">${fileIcon('folder')}<div><strong>${esc(source)}</strong><p>${state.sourceNames.length?state.sourceNames.length+' 个所选文件 · 仅使用名称演示':'6 个项目 · 示例来源'}</p></div></div><div class="field"><label for="archive-name">压缩包名称</label><input id="archive-name" name="name" value="${esc(d.name||'项目素材.7z')}" aria-describedby="archive-name-error" autofocus><span class="inline-error" id="archive-name-error"></span></div><div class="field"><label for="create-destination">保存到</label><input id="create-destination" name="destination" value="${esc(d.destination||'D:\\工作\\归档')}" aria-describedby="create-destination-hint create-destination-error"><span class="hint" id="create-destination-hint">原型路径，仅用于演示；不会写入磁盘。</span><span class="inline-error" id="create-destination-error"></span></div><div class="form-columns"><div class="field"><label for="format">压缩格式</label><select id="format" name="format"><option value="7z">7z · 更高压缩率</option><option value="zip" disabled>ZIP · 完整引擎接入后可用</option></select></div><div class="field"><label for="level">压缩级别</label><select id="level" name="level">${[['normal','标准（推荐）'],['fast','更快'],['ultra','更小']].map(([v,t])=>`<option value="${v}" ${d.level===v?'selected':''}>${t}</option>`).join('')}</select></div></div><details><summary>高级设置</summary><div class="form-columns"><div class="field"><label for="method">压缩方法</label><select id="method" name="method"><option>LZMA2</option></select></div><div class="field"><label for="threads">线程数</label><select id="threads" name="threads"><option>自动</option><option>2</option><option>4</option><option>8</option></select></div></div><p class="notice">正式版将由引擎估算内存占用。分卷、字典与固实参数将在能力验证后接入。</p></details><div class="field"><label for="password">密码（可选）</label><div class="password-row"><input id="password" name="password" type="password" autocomplete="new-password" placeholder="留空则不加密"><button onclick="handleClick(event)" class="btn" type="button" data-action="show-password" aria-label="显示密码">${icon('eye')}</button></div></div><label class="checkbox-label"><input type="checkbox" name="encryptNames" id="encrypt-names" disabled>加密文件名 <span class="muted small">设置密码后可选</span></label>`,`<button onclick="handleClick(event)" type="button" class="btn" data-action="close-dialog">取消</button><button onclick="handleClick(event)" class="btn primary" type="submit">开始压缩演示</button>`,data=>{const name=String(data.get('name'));if(fieldError('archive-name',validateName(name)))return;if(fieldError('create-destination',!String(data.get('destination')).trim()?'请输入保存目录。':''))return;saveDraft();dialog.close();addTask(name,'压缩',String(data.get('destination')));});$('#dialog-form').dataset.kind='create';if(d.threads)$('#threads').value=d.threads;$('#password').addEventListener('input',e=>{const c=$('#encrypt-names');c.disabled=!e.target.value;if(c.disabled)c.checked=false;});}
function extractDialog(){const d=state.extractDraft;showDialog('解压到','选择文件的落脚处。',`<div class="source-summary">${fileIcon('7z')}<div><strong>${esc(state.archiveName)}</strong><p>${state.selected.size?'选中的 '+state.selected.size+' 个项目':'压缩包中的全部内容'} · 示例归档</p></div></div><div class="field"><label for="extract-destination">目标目录</label><input id="extract-destination" name="destination" value="${esc(d.destination||'D:\\工作\\解压')}" aria-describedby="extract-destination-hint extract-destination-error" autofocus><span class="hint" id="extract-destination-hint">示例路径；正式版使用 Windows 文件夹选择器。</span><span class="inline-error" id="extract-destination-error"></span></div><label class="checkbox-label"><input type="checkbox" name="subfolder" checked>新建与压缩包同名的文件夹</label><div class="field"><label for="conflict-policy">遇到同名文件</label><select id="conflict-policy" name="conflict"><option value="ask">每次询问（推荐）</option><option value="rename">自动重命名，保留两者</option><option value="skip">跳过已有文件</option></select></div><label class="checkbox-label"><input type="checkbox" name="openAfter">完成后打开文件夹（正式版行为）</label><div class="notice">不会覆盖源压缩包。原型仅演示设置与进度，不写入目标目录。</div><button onclick="handleClick(event)" type="button" class="btn ghost" data-action="conflict-demo" style="margin-top:12px">演示同名冲突 →</button>`,`<button onclick="handleClick(event)" type="button" class="btn" data-action="close-dialog">取消</button><button onclick="handleClick(event)" class="btn primary" type="submit">开始解压演示</button>`,data=>{if(fieldError('extract-destination',!String(data.get('destination')).trim()?'请输入目标目录。':''))return;saveDraft();dialog.close();addTask(state.archiveName,'解压',String(data.get('destination')));});$('#dialog-form').dataset.kind='extract';$('#conflict-policy').value=d.conflict||'ask';$('#dialog-form').elements.subfolder.checked=d.subfolder!==false;$('#dialog-form').elements.openAfter.checked=!!d.openAfter;}
function confirmation(title,body,label,callback){showDialog(title,'',`<p>${body}</p>`,`<button onclick="handleClick(event)" class="btn" type="button" data-action="close-dialog" autofocus>返回</button><button onclick="handleClick(event)" class="btn danger" type="submit">${label}</button>`,()=>{dialog.close();callback();});}
function conflictDialog(){saveDraft();showDialog('已存在同名文件','演示状态 · 不会修改任何文件',`<p><strong>产品设计说明.pdf</strong> 已存在于目标目录。</p><div class="conflict-pair"><div><h3>目标中的文件</h3><p>8.2 MB</p><p class="muted">2026/11/01 10:20</p></div><div><h3>压缩包中的文件</h3><p>8.6 MB</p><p class="muted">2026/11/02 18:05</p></div></div><label class="checkbox-label"><input type="checkbox" id="apply-conflicts">应用到本次剩余冲突</label><p class="notice">保留两者时，新文件将命名为「产品设计说明 (2).pdf」。替换会覆盖目标文件，正式版执行前必须明确本次范围。</p>`,`<button onclick="handleClick(event)" class="btn" type="button" data-action="conflict-choice" data-choice="跳过">跳过</button><button onclick="handleClick(event)" class="btn danger" type="button" data-action="conflict-choice" data-choice="替换">替换</button><button onclick="handleClick(event)" class="btn primary" type="button" data-action="conflict-choice" data-choice="保留两者" autofocus>保留两者</button>`);}
function addTask(name,verb,destination){const t={id:state.nextId++,name,verb,destination,status:'running',progress:0};state.tasks.unshift(t);state.page='tasks';render();notify('已添加'+verb+'模拟任务。');}
setInterval(()=>{let changed=false;state.tasks.forEach(t=>{if(t.status==='running'){t.progress=Math.min(100,t.progress+5);if(t.progress===100){t.status='completed';notify(t.name+' 演示已完成，未生成实际文件。');changed=true;}if(state.page==='tasks'){const el=$(`[data-task="${t.id}"]`);if(el&&t.status==='running'){const bar=$('.bar',el);bar.setAttribute('aria-valuenow',t.progress);$('span',bar).style.width=t.progress+'%';$('[data-task-progress]',el).textContent=t.progress+'%';}}}});if(changed){navigation();if(state.page==='tasks')render(false);}const n=state.tasks.filter(t=>t.status==='running').length;$('#footer-state').textContent=n?n+' 个模拟任务进行中':'就绪';},600);

function handleClick(e){const page=e.target.closest('[data-page]');if(page){state.page=page.dataset.page;render();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
  if(a==='open'||a==='recent'){if(a==='recent')state.archiveName=state.history[Number(b.dataset.index)].name;state.folder='';state.query='';state.selected.clear();state.page='archive';state.loadError=false;render();}
  else if(a==='preview-file'||a==='preview-selected'){const all=state.folder?children[state.folder]:sample;const f=all.find(f=>f.id===(b.dataset.id||[...state.selected][0]));if(f)openPreview(f);}
  else if(a.startsWith('preview-'))previewAction(a);
  else if(a==='archive-menu')showArchiveContextMenu(b);
  else if(a==='create')createDialog();
  else if(a==='pick-source')$('#source-picker').click();
  else if(a==='extract')extractDialog();
  else if(a==='close-dialog')closeDialog();
  else if(a==='clear-history')confirmation('清空最近记录？','将移除最近使用的示例记录，原始文件不受影响。','清空记录',()=>{state.history=[];render();notify('最近记录已清空。');});
  else if(a==='sort'){state.asc=state.sort===b.dataset.sort?!state.asc:true;state.sort=b.dataset.sort;refreshTable();}
  else if(a==='file'){const f=(state.folder?children[state.folder]:sample).find(f=>f.id===b.dataset.id);if(f.type==='folder'){state.folder=f.id;state.query='';state.selected.clear();render();}else{state.selected=new Set([f.id]);state.details=true;render(false);const source=$('[data-action="file"][data-id="'+f.id+'"]');if(source)source.focus();openPreview(f);}}
  else if(a==='root'){state.folder='';state.query='';state.selected.clear();render();}
  else if(a==='clear-search'){state.query='';state.selected.clear();$('#file-search').value='';refreshTable();$('#file-search').focus();}
  else if(a==='toggle-details'){state.details=!state.details;render(false);}
  else if(a==='test')addTask(state.archiveName,'测试完整性','仅读取 · 示例');
  else if(a==='load-error'){state.loadError=true;render();}
  else if(a==='retry-load'){state.loadError=false;render();}
  else if(a==='show-password'){const p=$('#password');p.type=p.type==='password'?'text':'password';b.setAttribute('aria-label',p.type==='password'?'显示密码':'隐藏密码');b.setAttribute('aria-pressed',String(p.type==='text'));}
  else if(a==='conflict-demo')conflictDialog();
  else if(a==='conflict-choice'){const choice=b.dataset.choice;const many=$('#apply-conflicts').checked;dialog.close();notify('冲突演示：'+choice+(many?'，应用到本次剩余冲突。':'，仅此文件。'));extractDialog();}
  else if(a==='pause-task'){const t=state.tasks.find(t=>t.id===Number(b.dataset.id));t.status=t.status==='paused'?'running':'paused';render(false);}
  else if(a==='cancel-task'){const t=state.tasks.find(t=>t.id===Number(b.dataset.id));confirmation('取消这个任务？',`将停止「${esc(t.name)}」的模拟进度。没有实际文件需要清理。`,'取消任务',()=>{if(t.status==='completed'){notify('任务演示已完成，无需取消。');return;}t.status='cancelled';render(false);notify('模拟任务已取消。');});}
  else if(a==='failure-task'){state.tasks.unshift({id:state.nextId++,name:'项目备份.7z',verb:'压缩',destination:'C:\\受限目录',status:'failed',progress:18});render(false);}
  else if(a==='retry-task'){const t=state.tasks.find(t=>t.id===Number(b.dataset.id));showDialog('修改目标目录','失败配置仍保留，可修改后重新开始。',`<div class="field"><label for="retry-destination">目标目录</label><input id="retry-destination" name="destination" value="${esc(t.destination)}" autofocus aria-describedby="retry-destination-error"><span class="inline-error" id="retry-destination-error"></span></div><p class="notice">示例建议目录：D:\\工作\\归档。重试会重新启动模拟进度。</p>`,`<button onclick="handleClick(event)" class="btn" type="button" data-action="close-dialog">取消</button><button onclick="handleClick(event)" class="btn primary" type="submit">重新开始演示</button>`,data=>{if(fieldError('retry-destination',!String(data.get('destination')).trim()?'请输入目标目录。':''))return;t.destination=String(data.get('destination'));t.status='running';t.progress=0;dialog.close();render(false);});}
  else if(a==='task-result')showDialog('演示已完成','当前任务没有生成实际文件。',`<p>正式版将在这里展示真实输出大小、耗时和结果目录，并提供打开文件夹与查看归档入口。</p><p class="notice" style="margin-top:16px">本轮用于评审任务反馈，真实引擎尚未接入。</p>`,`<button onclick="handleClick(event)" class="btn primary" type="button" data-action="close-dialog">知道了</button>`);
  else if(a==='pick-icon'){$('#icon-picker').value='';$('#icon-picker').click();}
  else if(a==='reset-icon'){if(customUrl)URL.revokeObjectURL(customUrl);customUrl=null;state.brand='../图标/logo.png';render(false);notify('已恢复默认应用内图标。');}
}
document.addEventListener('change',e=>{if(e.target.name==='theme'){setTheme(e.target.value);return;}if(e.target.matches('[data-select]')){const id=e.target.dataset.select;e.target.checked?state.selected.add(id):state.selected.delete(id);refreshTable();const c=$(`[data-select="${id}"]`);if(c)c.focus();}if(e.target.id==='select-all'){const checked=e.target.checked;state.selected.clear();if(checked)archiveRows().forEach(f=>state.selected.add(f.id));refreshTable();$('#select-all').focus();}});
let composing=false;
function search(e){if(e.target.id!=='file-search'||composing)return;state.query=e.target.value;state.selected.clear();refreshTable();}
document.addEventListener('compositionstart',e=>{if(e.target.id==='file-search')composing=true;});
document.addEventListener('compositionend',e=>{if(e.target.id==='file-search'){composing=false;search(e);}});
document.addEventListener('input',search);
document.addEventListener('keydown',e=>{if(e.isComposing||dialog.open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='o'){e.preventDefault();state.page='archive';render();}if(e.altKey&&e.key==='ArrowUp'&&state.page==='archive'){e.preventDefault();state.folder='';state.query='';state.selected.clear();render();}});
$('#source-picker').addEventListener('change',e=>{state.sourceNames=Array.from(e.target.files).map(f=>f.name);if(state.sourceNames.length)createDialog();e.target.value='';});
document.addEventListener('dragover',e=>{const z=e.target.closest('#dropzone');if(z){e.preventDefault();z.classList.add('dragover');}});
document.addEventListener('dragleave',e=>{const z=e.target.closest('#dropzone');if(z&&!z.contains(e.relatedTarget))z.classList.remove('dragover');});
document.addEventListener('drop',e=>{e.preventDefault();const z=$('#dropzone');if(!z||!z.contains(e.target))return;z.classList.remove('dragover');const files=Array.from(e.dataTransfer.files);if(!files.length)return;if(files.length===1&&/\.7z$/i.test(files[0].name)){state.archiveName=files[0].name;state.page='archive';state.folder='';state.selected.clear();state.query='';render();notify('仅使用拖入文件名，内容仍是示例归档。');}else{state.sourceNames=files.map(f=>f.name);createDialog();}});
document.addEventListener('dragover',e=>e.preventDefault());
$('#icon-picker').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const error=message=>{const el=$('#icon-error');if(el)el.textContent=message;};if(!/\.(png|ico)$/i.test(file.name)){error('请选择 PNG 或 ICO 图片，当前图标未更改。');return;}if(file.size>10*1024*1024){error('图片超过 10 MB，请选择更小的文件。');return;}const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(img.naturalWidth>4096||img.naturalHeight>4096)throw new Error('图片尺寸不能超过 4096 × 4096。');if(customUrl)URL.revokeObjectURL(customUrl);customUrl=url;state.brand=url;render(false);notify('已替换应用内图标，仅当前会话有效。');}catch(ex){URL.revokeObjectURL(url);error(ex.message.startsWith('图片尺寸')?ex.message:'无法读取图片，请换一个有效的 PNG / ICO 文件。');}});
render(false);
